contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address to, uint256 amt, uint256 allowed) public {
        require(to != address(this) && to != address(c));
        c.approve(address(this), allowed); if (__ESBMC_reverted()) return;
        uint256 bal0 = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 to0 = c.balanceOf(to); if (__ESBMC_reverted()) return;
        uint256 all0 = c.allowance(address(this), address(this)); if (__ESBMC_reverted()) return;
        bool reverted;
        c.transferFrom(address(this), to, amt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
        assert(
            (reverted
                ? (amt > bal0 || amt > all0)
                : (amt <= bal0 && amt <= all0))
            &&
            (!reverted
                ? (c.balanceOf(address(this)) == bal0 - amt
                   && c.balanceOf(to) == to0 + amt
                   && c.allowance(address(this), address(this)) == all0 - amt)
                : (c.balanceOf(address(this)) == bal0
                   && c.balanceOf(to) == to0
                   && c.allowance(address(this), address(this)) == all0))
        );
    }
    receive() external payable {}
}

